<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { api, ApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'
type Station={id:number;name:string;code:string;location:{name:string};address:string;opening_hours:Record<string,string>;capacity:number;status:string}
const stations=ref<Station[]>([]);const loading=ref(true);const error=ref('')
onMounted(async()=>{try{const response=await api<{data:{items:Station[]}}>('/stations/?page_size=100');stations.value=response.data.items}catch(reason){error.value=reason instanceof ApiError?reason.message:'无法读取服务站'}finally{loading.value=false}})
</script>
<template><div class="page"><header><p class="eyebrow">P13 · CAMPUS SERVICE NETWORK</p><h1 class="page-title">校园服务站</h1><p class="page-lead">查看开放状态、营业时间和所在区域。线下交接前需先在系统内完成认领批准与预约。</p></header><p v-if="loading" class="empty">正在读取站点…</p><p v-else-if="error" class="empty error">{{error}}</p><section v-else class="station-grid"><RouterLink v-for="station in stations" :key="station.id" :to="`/stations/${station.id}`" class="panel station"><div class="station-icon"><AppIcon name="map"/></div><span class="status-tag">{{station.status}}</span><h2>{{station.name}}</h2><p>{{station.location.name}} · {{station.address}}</p><dl><div><dt>工作日</dt><dd>{{station.opening_hours.weekdays??'未公布'}}</dd></div><div><dt>保管容量</dt><dd>{{station.capacity}}</dd></div></dl><footer>查看站点详情 <AppIcon name="arrow"/></footer></RouterLink></section></div></template>
<style scoped>.station-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin-top:36px}.station{position:relative;padding:26px;box-shadow:none}.station-icon{display:grid;place-items:center;width:50px;aspect-ratio:1;color:var(--ct-brand);border:1px solid var(--ct-border-strong);border-radius:14px;background:rgba(245,185,66,.06);font-size:25px}.station>.status-tag{position:absolute;top:26px;right:26px}.station h2{margin:24px 0 7px}.station p{color:var(--ct-text-muted)}dl{display:grid;grid-template-columns:1fr 1fr;gap:1px;margin:22px 0;background:var(--ct-border)}dl div{padding:13px;background:var(--ct-bg-soft)}dt{color:var(--ct-text-muted);font-size:11px}dd{margin:4px 0 0}footer{display:flex;justify-content:space-between;color:var(--ct-brand)}.empty{display:grid;place-items:center;min-height:300px}.error{color:var(--ct-danger)}@media(max-width:680px){.station-grid{grid-template-columns:1fr}}</style>
